using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Game.Configs;using Game.Runtime;
// Preparation uses the original setup compiler and captured immutable factory facts; no World is created.
internal static class S002DerivedConfigurationTool {
 static string Sha(string path){using var stream=File.OpenRead(path);using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 static JObject Descriptor(string path)=>new JObject{["path"]=path,["sha256"]=Sha(path)};
 static void RejectDerived(JObject request,SkirmishResolvedSetup setup,string sourceRoot,string output,JObject qualification,string name,string field,JToken value){string path=Path.Combine(output,"control-"+name+".json");var altered=(JObject)qualification.DeepClone();altered[field]=value;File.WriteAllText(path,altered.ToString()+"\n");var candidate=(JObject)request.DeepClone();candidate["s002_derived_seed"]=Descriptor(path);bool rejected=false;try{try{SourceMetadataCompatibility.Load(candidate,setup,sourceRoot,sourceRoot);}catch(InvalidDataException){rejected=true;}catch(NotSupportedException){rejected=true;}}finally{File.Delete(path);}if(!rejected)throw new InvalidDataException("Derived control accepted: "+name);}
 static void CheckInputs(JObject request){var graphRef=(JObject)request["source_config_graph"];var matrix=(JObject)request["setup_matrix"];if(graphRef==null||matrix==null)throw new InvalidDataException("Pinned source graph and matrix required");if(graphRef.Count!=2||matrix.Count!=2)throw new InvalidDataException("Exact input descriptors required");byte[] graphBytes=AutonomousWorld.PinnedFile((string)graphRef["path"],(string)graphRef["sha256"],16*1024*1024);AutonomousWorld.PinnedFile((string)matrix["path"],(string)matrix["sha256"],4*1024*1024);var graph=JObject.Parse(System.Text.Encoding.UTF8.GetString(graphBytes),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(!(graph["source_pins"] is JObject pins)||pins.Count==0)throw new InvalidDataException("Pinned source assets required");foreach(var pin in pins.Properties())AutonomousWorld.PinnedFile(pin.Name,(string)pin.Value,4*1024*1024);}
 static void Main(string[] args){
  if(args.Length!=4||!int.TryParse(args[1],out int seed)||!Path.IsPathRooted(args[0])||!Path.IsPathRooted(args[2])||!Path.IsPathRooted(args[3]))throw new ArgumentException("absolute initialization, Int32 seed, source root and fresh output directory required");
  string output=args[3];if(!Directory.Exists(output)||Directory.GetFileSystemEntries(output).Length!=0)throw new InvalidOperationException("Fresh empty output required");
  var request=JObject.Parse(File.ReadAllText(args[0]));if((string)request["mission_id"]!="S002"||request["s002_derived_seed"]!=null)throw new InvalidDataException("Original S002 initialization required");
  CheckInputs(request);var compile=typeof(MetadataBindingControls).GetMethod("Compile",BindingFlags.Static|BindingFlags.NonPublic);var setup=(SkirmishResolvedSetup)compile.Invoke(null,new object[]{request,seed});
  string nativeFactorySha=(string)request["metadata_compatibility"]?["sha256"];
  if(nativeFactorySha!="d2c9714d8f8a49cab62de59fe57dceff9cf6ab24b7d176608850a2bfcfd20383"&&nativeFactorySha!="50a86f262e48c07808a3e52e2efb1b8bf8c744c00f1fd1c4fbf01b2e0c0502f1")throw new InvalidDataException("Exact captured S002 metadata epoch required");
  var q=new JObject{["schema_version"]=1,["kind"]="S002SourceOnlyDerivedSeed",["mission"]="S002",["seed"]=setup.Seed,["target_setup_hash"]=setup.SetupHash,["origin_seed"]=104731,["origin_setup_hash"]=3657809016u,["native_factory_sha256"]=nativeFactorySha,["semantic_inputs_sha256"]="5f5f805b12440d38e45b65067bf216b9350d14026568cee565c9d39515386cdf",["diagnostic_only"]=true,["native_context_qualified"]=false,["mission_ready"]=false};
  string qualification=Path.Combine(output,"qualification.json");File.WriteAllText(qualification,q.ToString()+"\n");request["selection"]["seed"]=seed;request["s002_derived_seed"]=Descriptor(qualification);
  var binding=SourceMetadataCompatibility.Load(request,setup,args[2],args[2]);if(binding.NativeQualified||!binding.FactoryDomainQualified)throw new InvalidDataException("Derived factory scope mismatch");binding.VerifyUnchanged();
  RejectDerived(request,setup,args[2],output,q,"native-mismatch","native_factory_sha256",nativeFactorySha=="d2c9714d8f8a49cab62de59fe57dceff9cf6ab24b7d176608850a2bfcfd20383"?"50a86f262e48c07808a3e52e2efb1b8bf8c744c00f1fd1c4fbf01b2e0c0502f1":"d2c9714d8f8a49cab62de59fe57dceff9cf6ab24b7d176608850a2bfcfd20383");
  RejectDerived(request,setup,args[2],output,q,"semantic-mismatch","semantic_inputs_sha256",new string('0',64));
  RejectDerived(request,setup,args[2],output,q,"origin-mismatch","origin_setup_hash",3657809017u);
  RejectDerived(request,setup,args[2],output,q,"target-mismatch","target_setup_hash",setup.SetupHash^1u);
  RejectDerived(request,setup,args[2],output,q,"readiness-mismatch","mission_ready",true);
  CheckInputs(request);
  string initialization=Path.Combine(output,"initialization.json");File.WriteAllText(initialization,request.ToString()+"\n");Console.WriteLine("[S002DerivedConfiguration] result=Passed target_seed="+seed+" target_setup_hash="+setup.SetupHash+" native_context_qualified=false world_allocated=false");
 }
}
